exam.solution:
function receipt(item, rawPrice, quantity, rawPostage) {
  const price = Number(rawPrice);
  const postage = Number(rawPostage);
  const total = price * quantity + postage;
  return `${quantity} x ${item} = ${total} coins`;
}
